39	
40	    static QString OutFreqToLabel(Reference::OutFreq t)
41	    {
42	        switch(t) {
43	        case OutFreq::MHZ10: return "10 MHz";
44	        case OutFreq::MHZ100: return "100 MHz";
45	        case OutFreq::Off: return "Off";
