114	LibreVNADriver::LibreVNADriver()
115	{
116	    connected = false;
117	    skipOwnPacketHandling = false;
118	    isIdle = true;
119	    SApoints = 0;
120	    hardwareVersion = 0;
121	    protocolVersion = 0;
122	    setSynchronization(Synchronization::Disabled, false);
123	    manualControlDialog = nullptr;
124	
125	    // Add driver specific actions
126	
127	    auto startManualControl = [=](){
128	        manualControlDialog = nullptr;
129	        switch(hardwareVersion) {
130	        case 1:
131	            manualControlDialog = new ManualControlDialogV1(*this);
132	            break;
133	        case 0xD0:
134	            manualControlDialog = new ManualControlDialogVD0(*this);
135	            break;
136	        case 0xE0:
137	            manualControlDialog = new ManualControlDialogVE0(*this);
138	            break;
139	        case 0xFE:
140	            manualControlDialog = new ManualControlDialogVFE(*this);
141	            break;
142	        case 0xFF:
143	            manualControlDialog = new ManualControlDialogVFF(*this);
144	            break;
145	        }
146	        if(manualControlDialog) {
147	            manualControlDialog->show();
148	            connect(manualControlDialog, &QDialog::finished, this, [=](){
149	                manualControlDialog = nullptr;
150	            });
151	        }
152	    };
153	
154	    auto manual = new QAction("Manual Control");
155	    connect(manual, &QAction::triggered, this, startManualControl);
156	    specificActions.push_back(manual);
157	
158	    auto config = new QAction("Configuration");
159	    connect(config, &QAction::triggered, this, [=](){
160	        QDialog *d = nullptr;
161	        switch(hardwareVersion) {
162	        case 1:
163	            d = new DeviceConfigurationDialogV1(*this);
164	            break;
165	        case 0xD0:
166	            d = new DeviceConfigurationDialogVD0(*this);
167	            break;
168	        case 0xFE:
169	            d = new DeviceConfigurationDialogVFE(*this);
170	            break;
171	        case 0xFF:
172	            d = new DeviceConfigurationDialogVFF(*this);
173	            break;
174	        }
175	        if(d) {
176	            d->show();
177	        }
178	    });
179	    specificActions.push_back(config);
180	
181	    auto update = new QAction("Firmware Update");
182	    connect(update, &QAction::triggered, this, [=](){
183	       auto d = new FirmwareUpdateDialog(this);
184	       d->show();
185	    });
186	    specificActions.push_back(update);
187	
188	    auto sep = new QAction();
