480	bool LibreVNADriver::setVNA(const DeviceDriver::VNASettings &s, std::function<void (bool)> cb)
481	{
482	    if(!supports(Feature::VNA)) {
483	        qDebug() << "VNA does not support features \"VNA\" (has the DeviceInfo been received?)";
484	        return false;
485	    }
486	    if(s.excitedPorts.size() == 0) {
487	        return setIdle(cb);
488	    }
489	
490	    // create port->stage mapping
491	    portStageMapping.clear();
492	    for(unsigned int i=0;i<s.excitedPorts.size();i++) {
493	        portStageMapping[s.excitedPorts[i]] = i;
494	    }
495	
496	    Protocol::PacketInfo p = {};
497	    p.type = Protocol::PacketType::SweepSettings;
498	    p.settings.f_start = s.freqStart;
499	    p.settings.f_stop = s.freqStop;
500	    p.settings.points = s.points;
501	    p.settings.if_bandwidth = s.IFBW;
502	    p.settings.cdbm_excitation_start = s.dBmStart * 100;
503	    p.settings.cdbm_excitation_stop = s.dBmStop * 100;
504	    p.settings.stages = s.excitedPorts.size() - 1;
505	    auto dwell_us = s.dwellTime * 1e6;
506	    if(dwell_us < 0) {
507	        dwell_us = 0;
508	    } else if(dwell_us > UINT16_MAX) {
509	        dwell_us = UINT16_MAX;
510	    }
511	    p.settings.dwell_time = dwell_us;
512	    p.settings.suppressPeaks = VNASuppressInvalidPeaks ? 1 : 0;
513	    p.settings.fixedPowerSetting = VNAAdjustPowerLevel || s.dBmStart != s.dBmStop ? 0 : 1;
514	    p.settings.logSweep = s.logSweep ? 1 : 0;
515	
516	    zerospan = (s.freqStart == s.freqStop) && (s.dBmStart == s.dBmStop);
517	    p.settings.port1Stage = find(s.excitedPorts.begin(), s.excitedPorts.end(), 1) - s.excitedPorts.begin();
518	    p.settings.port2Stage = find(s.excitedPorts.begin(), s.excitedPorts.end(), 2) - s.excitedPorts.begin();
519	    p.settings.port3Stage = find(s.excitedPorts.begin(), s.excitedPorts.end(), 3) - s.excitedPorts.begin();
520	    p.settings.port4Stage = find(s.excitedPorts.begin(), s.excitedPorts.end(), 4) - s.excitedPorts.begin();
521	    p.settings.syncMode = (int) sync;
522	    p.settings.syncMaster = syncMaster ? 1 : 0;
523	
524	    isIdle = false;
525	    lastNonIdlePacket = p;
526	
527	    return SendPacket(p, [=](TransmissionResult r){
528	        if(cb) {
529	            cb(r == TransmissionResult::Ack);
530	        }
531	    });
532	}
