546	        return false;
547	    }
548	
549	    zerospan = s.freqStart == s.freqStop;
550	
551	    Protocol::PacketInfo p = {};
552	    p.type = Protocol::PacketType::SpectrumAnalyzerSettings;
553	    p.spectrumSettings.f_start = s.freqStart;
554	    p.spectrumSettings.f_stop = s.freqStop;
555	
556	    constexpr unsigned int maxSApoints = 1001;
