565	    p.spectrumSettings.WindowType = (int) s.window;
566	    p.spectrumSettings.SignalID = SASignalID ? 1 : 0;
567	    p.spectrumSettings.Detector = (int) s.detector;
568	    p.spectrumSettings.UseDFT = 0;
569	    if(!s.trackingGenerator && SAUseDFT && s.RBW <= SARBWLimitForDFT && s.freqStart != s.freqStop) {
570	        p.spectrumSettings.UseDFT = 1;
571	    }
572	    p.spectrumSettings.applyReceiverCorrection = 1;
573	    p.spectrumSettings.trackingGeneratorOffset = s.trackingOffset;
574	    p.spectrumSettings.trackingPower = s.trackingPower * 100;
575	
576	    p.spectrumSettings.trackingGenerator = s.trackingGenerator ? 1 : 0;
577	    p.spectrumSettings.trackingGeneratorPort = s.trackingPort - 1;
578	    p.spectrumSettings.syncMode = (int) sync;
579	    p.spectrumSettings.syncMaster = syncMaster ? 1 : 0;
580	
581	    isIdle = false;
582	    lastNonIdlePacket = p;
583	
584	    return SendPacket(p, [=](TransmissionResult r){
585	        if(cb) {
